/*
 * گزارش وضعیت تغییرات سیستم واگذاری اختیاری — Cloudflare Worker
 *
 * پیش‌نیازها (Settings در داشبورد Worker):
 *   - Binding از نوع KV namespace با نام متغیر  DATA
 *   - Secret با نام  ADMIN_PASSWORD  (رمز ویرایش)
 *
 * مسیرها:
 *   GET  /              صفحه‌ی گزارش با آخرین داده
 *   GET  /api/data      آخرین داده (عمومی، فقط خواندنی)
 *   POST /api/login     بررسی رمز
 *   PUT  /api/data      ذخیره‌ی نسخه‌ی جدید (رمز لازم)
 *   GET  /api/history   فهرست نسخه‌های قبلی (رمز لازم)
 *   POST /api/restore   بازگردانی یک نسخه‌ی قبلی (رمز لازم)
 */

const HTML = "<!DOCTYPE html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>وضعیت تغییرات سیستم واگذاری اختیاری</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;700;800&display=swap\" rel=\"stylesheet\">\n<style>\n/* طرح: سه بخش شماره‌دار با سربرگ مشکی‌ـ‌طلایی؛ هر وضعیت رنگ خودش را دارد و هیچ وضعیتی با دیگری ادغام نمی‌شود */\n:root{\n  --gold:#f0b323; --gold-deep:#a87a00; --ink:#1c1a17; --ink-2:#2b2824;\n  --bg:#efeee9; --surface:#ffffff; --surface-2:#f7f6f2; --line:#e1ddd2; --line-2:#cfc9bb;\n  --text:#1c1a17; --muted:#6a655b; --danger:#c0392b; --edit:#fff8e6;\n  --s-done:#2e9e6b; --s-exists:#2389a6; --s-inprog:#e9a700; --s-meeting:#e06a1b;\n  --s-print:#8459c0; --s-sanad:#c2428a; --s-rejected:#7d828c; --s-other:#4f6bd6;\n  --font:\"Vazirmatn\",Tahoma,\"Segoe UI\",sans-serif;\n  --r:14px;\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    color-scheme:dark;\n    --bg:#131210; --surface:#1e1c19; --surface-2:#262420; --line:#37332c; --line-2:#4a453b; --ink-2:#2b2824;\n    --text:#f1eee6; --muted:#a8a295; --gold-deep:#f0b323; --edit:#2c2617; --danger:#ef7a6c;\n    --s-done:#46c088; --s-exists:#3fb0cf; --s-inprog:#f3bd2e; --s-meeting:#f58a3c;\n    --s-print:#a985e0; --s-sanad:#e06aae; --s-rejected:#9da2ab; --s-other:#7d94ee;\n  }\n}\n:root[data-theme=\"dark\"]{\n  color-scheme:dark;\n  --bg:#131210; --surface:#1e1c19; --surface-2:#262420; --line:#37332c; --line-2:#4a453b; --ink-2:#2b2824;\n  --text:#f1eee6; --muted:#a8a295; --gold-deep:#f0b323; --edit:#2c2617; --danger:#ef7a6c;\n  --s-done:#46c088; --s-exists:#3fb0cf; --s-inprog:#f3bd2e; --s-meeting:#f58a3c;\n  --s-print:#a985e0; --s-sanad:#e06aae; --s-rejected:#9da2ab; --s-other:#7d94ee;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0}\nbody{background:var(--bg);color:var(--text);font-family:var(--font);font-size:15px;line-height:1.8;font-variant-numeric:tabular-nums}\nbody.editing{padding-bottom:86px}\nbutton,input,select,textarea{font:inherit;color:inherit}\nbutton{cursor:pointer}\n:focus-visible{outline:3px solid var(--gold);outline-offset:2px}\nh1,h2,h3{margin:0;text-wrap:balance;line-height:1.5}\n\n/* سربرگ صفحه */\n.band{background:var(--ink);color:#f6f2e7;border-bottom:5px solid var(--gold)}\n.band-in{max-width:1180px;margin:0 auto;padding:26px 20px 22px;display:flex;gap:18px;align-items:flex-end;justify-content:space-between;flex-wrap:wrap}\n.eyebrow{color:var(--gold);font-weight:700;font-size:13px}\n.band h1{font-size:clamp(20px,3.2vw,30px);font-weight:800}\n.band p{margin:6px 0 0;color:#c9c3b4;font-size:13.5px}\n.band-meta{display:flex;gap:10px;flex-wrap:wrap;align-items:center}\n.tag{border:1px solid #4a453b;border-radius:999px;padding:3px 14px;font-size:13px;color:#e9e3d3}\n.tag b{color:var(--gold);font-weight:700}\n.editbtn{background:var(--gold);color:var(--ink);border:0;border-radius:999px;padding:5px 18px;font-weight:800;font-size:13.5px}\n.editbtn:hover{filter:brightness(1.08)}\n\nmain{max-width:1180px;margin:0 auto;padding:24px 20px 40px;display:flex;flex-direction:column;gap:26px}\n\n/* بخش‌های اصلی: هر بخش قاب و سربرگ شماره‌دار خودش را دارد */\n.sec{background:var(--surface);border:1px solid var(--line-2);border-radius:var(--r);overflow:hidden;box-shadow:0 1px 0 rgba(0,0,0,.03)}\n.sec-h{display:flex;align-items:center;gap:14px;padding:14px 20px;background:var(--ink-2);color:#f6f2e7;border-bottom:3px solid var(--gold)}\n.sec-n{flex:none;width:34px;height:34px;border-radius:50%;background:var(--gold);color:var(--ink);display:grid;place-items:center;font-weight:800;font-size:16px}\n.sec-h h2{font-size:18px;font-weight:800}\n.sec-h p{margin:0;color:#c9c3b4;font-size:13px;line-height:1.6}\n.sec-b{padding:20px}\n\n/* بخش ۱: خلاصه وضعیت */\n.overview{display:grid;grid-template-columns:280px minmax(0,1fr);gap:26px;align-items:center}\n.donut-wrap{position:relative;max-width:270px;margin:0 auto;width:100%}\n.donut{width:100%;display:block;transform:rotate(-90deg)}\n.donut circle{fill:none;stroke-width:6.5;cursor:pointer;transition:stroke-width .15s, opacity .15s}\n.donut circle:hover,.donut circle.on{stroke-width:8.5}\n.donut.has-sel circle:not(.on){opacity:.3}\n.donut-c{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;pointer-events:none;text-align:center}\n.donut-c .n{font-size:40px;font-weight:800;line-height:1.2}\n.donut-c .t{font-size:13px;color:var(--muted);max-width:58%;line-height:1.5}\n.tiles{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n.tile{min-width:0;display:grid;grid-template-columns:1fr auto;gap:2px 12px;align-items:center;text-align:right;\n  background:color-mix(in srgb,var(--c) 8%,var(--surface));border:1px solid color-mix(in srgb,var(--c) 30%,var(--line));\n  border-inline-start:7px solid var(--c);border-radius:10px;padding:10px 14px;transition:box-shadow .15s, transform .15s}\n.tile:hover{transform:translateY(-1px);box-shadow:0 4px 14px rgba(0,0,0,.07)}\n.tile[aria-pressed=\"true\"]{box-shadow:0 0 0 2px var(--c)}\n.tile .name{font-weight:700;font-size:14px;line-height:1.6}\n.tile .pct{font-weight:800;font-size:22px;line-height:1.2}\n.tile .cnt{grid-column:1/-1;font-size:12.5px;color:var(--muted)}\n.tile .track{grid-column:1/-1;height:6px;border-radius:3px;background:var(--surface);border:1px solid var(--line);overflow:hidden}\n.tile .track i{display:block;height:100%;background:var(--c);transition:width .3s}\n\n.insights{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:20px;padding-top:18px;border-top:1px dashed var(--line-2)}\n.ins{background:var(--surface-2);border:1px solid var(--line);border-inline-start:4px solid var(--ic,var(--gold));border-radius:10px;padding:10px 14px;font-size:14px}\n.ins .k{display:block;font-size:12px;color:var(--muted);font-weight:700}\n.ins b{font-weight:800}\n\n/* بخش ۲: زیرسیستم‌ها */\n.subs{display:flex;flex-direction:column}\n.sub{display:grid;grid-template-columns:30px minmax(170px,280px) 1fr 96px;gap:14px;align-items:center;padding:10px 4px;border-bottom:1px solid var(--line)}\n.sub:nth-child(even){background:var(--surface-2)}\n.sub:last-child{border-bottom:0}\n.sub .ix{font-weight:800;color:var(--muted);font-size:13px;text-align:center}\n.sub-name{background:none;border:0;padding:2px 6px;border-radius:8px;text-align:right;font-weight:700;font-size:14px;line-height:1.6}\n.sub-name:hover{color:var(--gold-deep);text-decoration:underline;text-underline-offset:4px}\n.sub-name small{display:block;font-weight:400;color:var(--muted);font-size:12.5px;text-decoration:none}\n.bar{display:flex;height:28px;border-radius:7px;overflow:hidden;gap:2px;background:var(--surface-2)}\n.seg{border:0;padding:0;min-width:14px;background:var(--c);color:var(--on,#fff);font-weight:800;font-size:13px;transition:filter .15s}\n.seg:hover{filter:brightness(1.12)}\n.sub-pct{font-weight:800;font-size:14px;text-align:left;white-space:nowrap;color:var(--s-done)}\n.sub-pct small{display:block;font-weight:400;color:var(--muted);font-size:11.5px}\n.legend{display:flex;flex-wrap:wrap;gap:6px 16px;margin-top:14px;padding-top:12px;border-top:1px dashed var(--line-2);font-size:12.5px;color:var(--muted)}\n.legend span{display:inline-flex;align-items:center;gap:6px}\n.dot{width:10px;height:10px;border-radius:3px;background:var(--c);flex:none;display:inline-block}\n\n/* بخش ۳: شرح نیازمندی */\n.tools{display:flex;gap:10px;flex-wrap:wrap;align-items:center;padding:14px 20px;background:var(--surface-2);border-bottom:1px solid var(--line)}\n#q{flex:1 1 240px;border:1px solid var(--line-2);background:var(--surface);border-radius:10px;padding:8px 14px}\n.filters{display:flex;gap:8px;flex-wrap:wrap;align-items:center;padding:10px 20px 0}\n.filters:empty{display:none}\n.chip{border:1px solid var(--line-2);background:var(--surface);border-radius:999px;padding:3px 12px;font-size:13px;display:inline-flex;gap:8px;align-items:center}\n.chip:hover{border-color:var(--gold)}\n.btn{border:1px solid var(--ink);background:var(--ink);color:#f6f2e7;border-radius:10px;padding:7px 16px;font-size:13.5px;font-weight:700}\n.btn.ghost{background:transparent;color:var(--text);border-color:var(--line-2)}\n.btn.gold{background:var(--gold);border-color:var(--gold);color:var(--ink)}\n.btn:hover{border-color:var(--gold)}\n.btn[disabled]{opacity:.45;cursor:not-allowed}\n.edit-only{display:none!important}\nbody.editing .edit-only{display:inline-flex!important}\n.count{color:var(--muted);font-size:13.5px;padding:10px 20px 0}\n.systems{display:flex;flex-direction:column;gap:14px;padding:14px 20px 20px}\n\n/* قاب هر زیرسیستم */\n.sys{border:1px solid var(--line-2);border-radius:12px;overflow:hidden;background:var(--surface-2)}\n.sys-h{display:flex;align-items:stretch;background:var(--surface);border-bottom:1px solid transparent}\n.sys.open .sys-h{border-bottom-color:var(--line-2)}\n.sys-t{flex:1;min-width:0;display:grid;grid-template-columns:auto minmax(0,1fr) minmax(120px,220px) auto;gap:14px;align-items:center;background:none;border:0;padding:12px 16px;text-align:right}\n.sys-t:hover{background:var(--surface-2)}\n.sys-ix{width:38px;height:38px;border-radius:10px;background:var(--ink);color:var(--gold);display:grid;place-items:center;font-weight:800;font-size:14px}\n.sys-name{font-weight:800;font-size:15.5px;line-height:1.6}\n.sys-name small{display:block;font-weight:500;color:var(--muted);font-size:12.5px}\n.sys-bar{display:flex;height:10px;border-radius:5px;overflow:hidden;gap:2px;background:var(--line)}\n.sys-bar i{display:block;background:var(--c)}\n.chev{width:28px;height:28px;border-radius:50%;border:1px solid var(--line-2);display:grid;place-items:center;font-size:13px;transition:transform .2s;color:var(--muted)}\n.sys.open .chev{transform:rotate(180deg)}\n.sys-add{border:0;border-inline-start:1px solid var(--line);background:var(--gold);color:var(--ink);font-weight:800;font-size:13px;padding:0 14px}\n.sys-body{display:none;padding:14px;flex-direction:column;gap:10px}\n.sys.open .sys-body{display:flex}\n\n/* کارت هر نیازمندی */\n.req{display:grid;grid-template-columns:36px minmax(0,1fr) auto;gap:8px 14px;align-items:start;background:var(--surface);border:1px solid var(--line);border-inline-start:6px solid var(--c);border-radius:10px;padding:12px 14px}\n.req .no{width:30px;height:30px;border-radius:50%;background:var(--surface-2);border:1px solid var(--line-2);display:grid;place-items:center;font-weight:800;font-size:12.5px;color:var(--muted)}\n.req .tx{max-width:78ch;white-space:pre-line;padding-top:2px}\n.pill{display:inline-flex;align-items:center;gap:7px;border-radius:999px;padding:3px 12px;font-size:12.5px;font-weight:700;max-width:250px;line-height:1.7;\n  background:color-mix(in srgb,var(--c) 14%,var(--surface));color:var(--text);border:1px solid color-mix(in srgb,var(--c) 45%,var(--line))}\n.pill .dot{width:8px;height:8px;border-radius:50%}\n.note{grid-column:2/-1;background:color-mix(in srgb,var(--gold) 9%,var(--surface));border:1px solid color-mix(in srgb,var(--gold) 35%,var(--line));border-radius:8px;padding:8px 12px;font-size:13.5px;white-space:pre-line}\n.note b{display:block;font-size:12px;color:var(--gold-deep);font-weight:800}\n.empty{padding:26px;text-align:center;color:var(--muted)}\n\n/* حالت ویرایش ردیف */\n.req.ed{grid-template-columns:36px minmax(0,1fr) 250px}\n.req.dirty{background:var(--edit);box-shadow:0 0 0 2px var(--gold)}\n.req.new{box-shadow:0 0 0 2px var(--s-done)}\n.req.removed{opacity:.5}\n.req.removed .tx-in{text-decoration:line-through}\n.req .side{display:flex;flex-direction:column;gap:8px}\n.req select{width:100%;border:1px solid var(--line);border-inline-start:6px solid var(--c);background:var(--surface-2);border-radius:8px;padding:5px 8px;font-size:13.5px;font-weight:700}\n.req textarea{width:100%;border:1px solid var(--line);background:var(--surface-2);border-radius:8px;padding:6px 10px;resize:vertical;min-height:58px;line-height:1.7}\n.req textarea.nt{grid-column:2/3;min-height:38px;font-size:13.5px}\n.req .rm{align-self:flex-start;background:none;border:1px solid var(--line);border-radius:8px;padding:2px 10px;font-size:12.5px;color:var(--danger)}\n.req .rm:hover{border-color:var(--danger)}\n.lbl-s{font-size:12px;color:var(--muted)}\n\n/* نوار ویرایش */\n.editbar{position:fixed;inset-inline:0;bottom:0;z-index:20;background:var(--ink);color:#f6f2e7;border-top:4px solid var(--gold);display:none}\nbody.editing .editbar{display:block}\n.editbar-in{max-width:1180px;margin:0 auto;padding:12px 20px;display:flex;gap:10px;align-items:center;flex-wrap:wrap}\n.editbar .state{flex:1 1 220px;font-size:14px}\n.editbar .state b{color:var(--gold)}\n.editbar .btn.ghost{color:#f6f2e7;border-color:#4a453b}\n\n/* پنجره */\n.modal{position:fixed;inset:0;z-index:30;background:rgba(15,14,12,.55);display:none;align-items:center;justify-content:center;padding:16px}\n.modal.open{display:flex}\n.dlg{background:var(--surface);color:var(--text);border-radius:var(--r);border-top:5px solid var(--gold);width:100%;max-width:440px;padding:22px;display:flex;flex-direction:column;gap:12px;max-height:90vh;overflow:auto}\n.dlg h3{font-size:17px;font-weight:800}\n.dlg label{display:flex;flex-direction:column;gap:4px;font-size:13.5px;font-weight:700}\n.dlg input{border:1px solid var(--line);background:var(--surface-2);border-radius:10px;padding:8px 12px;font-weight:400}\n.dlg .row{display:flex;gap:10px;justify-content:flex-start;flex-wrap:wrap}\n.dlg .err{color:var(--danger);font-size:13.5px;min-height:1em}\n.hint{color:var(--muted);font-size:13px}\n.hist{display:flex;flex-direction:column;gap:8px}\n.hist div{display:flex;justify-content:space-between;align-items:center;gap:10px;border:1px solid var(--line);border-radius:10px;padding:8px 12px;font-size:13.5px}\n.toast{position:fixed;z-index:40;top:16px;inset-inline:0;margin:0 auto;width:max-content;max-width:calc(100% - 32px);background:var(--ink);color:#f6f2e7;border:1px solid var(--gold);border-radius:10px;padding:8px 18px;font-size:14px;display:none}\n.toast.show{display:block}\n.toast.bad{border-color:var(--danger)}\n\nfooter{max-width:1180px;margin:0 auto;padding:0 20px 34px;color:var(--muted);font-size:12.5px}\n\n@media (max-width:900px){\n  .overview{grid-template-columns:1fr}\n  .insights{grid-template-columns:1fr}\n  .sub{grid-template-columns:26px 1fr 80px}\n  .sub .bar{grid-column:2/-1;grid-row:2}\n  .sys-t{grid-template-columns:auto minmax(0,1fr) auto}\n  .sys-bar{grid-column:2/3;grid-row:2}\n  .req.ed{grid-template-columns:30px minmax(0,1fr)}\n  .req.ed .side{grid-column:2}\n  .req textarea.nt{grid-column:2}\n}\n@media (max-width:560px){\n  .tiles{grid-template-columns:1fr}\n  .req{grid-template-columns:30px minmax(0,1fr)}\n  .req .pill{grid-column:2;justify-self:start}\n  .note{grid-column:2}\n  .sec-b,.systems{padding-inline:12px}\n}\n@media (prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}\n</style>\n</head>\n<body>\n<header class=\"band\">\n  <div class=\"band-in\">\n    <div>\n      <div class=\"eyebrow\">گزارش تحلیلی · اتکایی واگذاری اختیاری</div>\n      <h1>آخرین وضعیت بندهای تغییرات اعلامی سیستم واگذاری</h1>\n      <p>روی هر وضعیت یا زیرسیستم کلیک کنید تا شرح نیازمندی‌های همان مورد در بخش ۳ باز شود.</p>\n    </div>\n    <div class=\"band-meta\">\n      <span class=\"tag\">آخرین به‌روزرسانی <b id=\"upd\"></b></span>\n      <span class=\"tag\"><b id=\"tcount\"></b> نیازمندی در <b id=\"ccount\"></b> زیرسیستم</span>\n      <button class=\"editbtn\" id=\"editbtn\" type=\"button\">ویرایش وضعیت‌ها</button>\n    </div>\n  </div>\n</header>\n\n<main>\n  <section class=\"sec\" aria-labelledby=\"h1s\">\n    <div class=\"sec-h\"><span class=\"sec-n\">۱</span><div><h2 id=\"h1s\">خلاصه وضعیت</h2><p>سهم هر وضعیت از کل نیازمندی‌ها؛ هر وضعیت جداگانه شمرده شده است.</p></div></div>\n    <div class=\"sec-b\">\n      <div class=\"overview\">\n        <div class=\"donut-wrap\">\n          <svg class=\"donut\" id=\"donut\" viewBox=\"0 0 42 42\" role=\"img\" aria-label=\"نمودار حلقه‌ای وضعیت نیازمندی‌ها\"></svg>\n          <div class=\"donut-c\"><div class=\"n\" id=\"dn\"></div><div class=\"t\" id=\"dt\"></div></div>\n        </div>\n        <div class=\"tiles\" id=\"tiles\"></div>\n      </div>\n      <div class=\"insights\" id=\"insights\"></div>\n    </div>\n  </section>\n\n  <section class=\"sec\" aria-labelledby=\"h2s\">\n    <div class=\"sec-h\"><span class=\"sec-n\">۲</span><div><h2 id=\"h2s\">وضعیت به تفکیک زیرسیستم</h2><p>هر نوار ترکیب وضعیت‌های یک زیرسیستم است. عدد سبز سمت چپ فقط سهم «انجام شده روی محیط داخلی» است.</p></div></div>\n    <div class=\"sec-b\">\n      <div class=\"subs\" id=\"subs\"></div>\n      <div class=\"legend\" id=\"legend\"></div>\n    </div>\n  </section>\n\n  <section class=\"sec\" id=\"details\" aria-labelledby=\"h3s\">\n    <div class=\"sec-h\"><span class=\"sec-n\">۳</span><div><h2 id=\"h3s\">شرح نیازمندی</h2><p>نیازمندی‌ها به تفکیک زیرسیستم. روی سربرگ هر زیرسیستم بزنید تا باز یا بسته شود.</p></div></div>\n    <div class=\"tools\">\n      <input id=\"q\" type=\"search\" placeholder=\"جست‌وجو در شرح نیازمندی و توضیحات…\" aria-label=\"جست‌وجو\">\n      <button class=\"btn ghost\" id=\"toggleall\" type=\"button\">باز کردن همه</button>\n      <button class=\"btn ghost\" id=\"clear\" type=\"button\">حذف فیلترها</button>\n      <button class=\"btn gold edit-only\" id=\"addcat\" type=\"button\">+ زیرسیستم جدید</button>\n      <button class=\"btn ghost edit-only\" id=\"upbtn\" type=\"button\">جایگزینی با اکسل</button>\n      <input id=\"file\" type=\"file\" accept=\".xlsx,.xls\" hidden>\n    </div>\n    <div class=\"filters\" id=\"chips\"></div>\n    <div class=\"count\" id=\"count\"></div>\n    <div class=\"systems\" id=\"list\"></div>\n  </section>\n</main>\n\n<footer>\n  همه‌ی اعداد از روی وضعیت تک‌تک نیازمندی‌ها محاسبه می‌شوند و هر وضعیت جداگانه شمرده شده است.\n  «انجام شده روی محیط داخلی» به معنی استقرار در محیط عملیاتی نیست.\n</footer>\n\n<div class=\"editbar\" role=\"region\" aria-label=\"نوار ویرایش\">\n  <div class=\"editbar-in\">\n    <div class=\"state\" id=\"estate\"></div>\n    <button class=\"btn gold\" id=\"save\" type=\"button\">ذخیره و انتشار</button>\n    <button class=\"btn ghost\" id=\"discard\" type=\"button\">لغو تغییرات</button>\n    <button class=\"btn ghost\" id=\"histbtn\" type=\"button\">نسخه‌های قبلی</button>\n    <button class=\"btn ghost\" id=\"exit\" type=\"button\">خروج از ویرایش</button>\n  </div>\n</div>\n\n<div class=\"modal\" id=\"m-login\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"lg-t\">\n  <form class=\"dlg\" id=\"lg-form\">\n    <h3 id=\"lg-t\">ورود به حالت ویرایش</h3>\n    <label>نام شما (در تاریخچه ثبت می‌شود)<input id=\"lg-name\" autocomplete=\"name\" maxlength=\"60\" required></label>\n    <label>رمز ویرایش<input id=\"lg-pw\" type=\"password\" autocomplete=\"current-password\" required></label>\n    <div class=\"err\" id=\"lg-err\" role=\"alert\"></div>\n    <div class=\"row\"><button class=\"btn gold\" type=\"submit\" id=\"lg-go\">ورود</button><button class=\"btn ghost\" type=\"button\" data-close>انصراف</button></div>\n  </form>\n</div>\n\n<div class=\"modal\" id=\"m-cat\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"ct-t\">\n  <form class=\"dlg\" id=\"ct-form\">\n    <h3 id=\"ct-t\">زیرسیستم جدید</h3>\n    <label>نام زیرسیستم<input id=\"ct-name\" maxlength=\"200\" required></label>\n    <div class=\"row\"><button class=\"btn gold\" type=\"submit\">افزودن</button><button class=\"btn ghost\" type=\"button\" data-close>انصراف</button></div>\n  </form>\n</div>\n\n<div class=\"modal\" id=\"m-hist\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"hs-t\">\n  <div class=\"dlg\">\n    <h3 id=\"hs-t\">نسخه‌های قبلی</h3>\n    <p class=\"hint\" style=\"margin:0\">بازگردانی، آن نسخه را به‌عنوان نسخه‌ی جدید منتشر می‌کند. نسخه‌ی فعلی هم در تاریخچه می‌ماند.</p>\n    <div class=\"hist\" id=\"hs-list\"></div>\n    <div class=\"err\" id=\"hs-err\" role=\"alert\"></div>\n    <div class=\"row\"><button class=\"btn ghost\" type=\"button\" data-close>بستن</button></div>\n  </div>\n</div>\n\n<div class=\"toast\" id=\"toast\" role=\"status\"></div>\n\n<script>\nvar BOOT = /*__BOOT__*/null;\n/* BOOT = {version, updatedAt, updatedBy, label, rows:[{id,cat,req,status,note}], readonly?} */\n\n/* هر وضعیت رنگ مستقل خودش را دارد؛ هیچ گروه‌بندی یا ادغامی بین وضعیت‌ها انجام نمی‌شود */\nvar KNOWN = [\n  {k:'done',    re:/انجام شده/,  color:'var(--s-done)',     on:'#fff'},\n  {k:'exists',  re:/وجود دارد/,  color:'var(--s-exists)',   on:'#fff'},\n  {k:'inprog',  re:/در حال/,     color:'var(--s-inprog)',   on:'#1c1a17'},\n  {k:'meeting', re:/جلسه/,       color:'var(--s-meeting)',  on:'#fff'},\n  {k:'print',   re:/چاپی/,       color:'var(--s-print)',    on:'#fff'},\n  {k:'sanad',   re:/سند/,        color:'var(--s-sanad)',    on:'#fff'},\n  {k:'rejected',re:/^رد /,       color:'var(--s-rejected)', on:'#fff'}\n];\nvar CANON = ['انجام شده روی محیط داخلی','نیازمندی مطرح شده در سیستم وجود دارد','در حال انجام','نیاز به جلسه با بیمه پاسارگاد','نیاز به ارائه نمونه چاپی از طرف بیمه پاسارگاد','نیاز به ارائه نحوه سند زنی از طرف بیمه پاسارگاد','رد درخواست'];\nfunction meta(status){\n  for (var i=0;i<KNOWN.length;i++) if (KNOWN[i].re.test(status)) return KNOWN[i];\n  return {k:'other', color:'var(--s-other)', on:'#fff'};\n}\nfunction isDone(s){return meta(s).k==='done'}\n/* ترتیب ثابت نمایش وضعیت‌ها: به ترتیب فهرست بالا، وضعیت‌های ناشناخته در انتها */\nfunction stOrder(a,b){\n  var ia=CANON.indexOf(a), ib=CANON.indexOf(b);\n  return (ia<0?99:ia)-(ib<0?99:ib) || (a<b?-1:1);\n}\n\nvar SERVER = BOOT || {version:0, rows:[], readonly:true};\nvar RAW = clone(SERVER.rows);\nvar ORIG = {};\nvar REMOVED = {};\nvar AUTH = null;\nvar OPEN = {};                          /* زیرسیستم‌های باز در بخش ۳ */\nvar state = {status:null, cat:null, q:''};\nindexOrig();\n\nvar nf = new Intl.NumberFormat('fa-IR');\nvar pf = new Intl.NumberFormat('fa-IR',{maximumFractionDigits:1});\nfunction N(n){return nf.format(n)}\nfunction NN(n){return new Intl.NumberFormat('fa-IR',{minimumIntegerDigits:2}).format(n)}\nfunction P(n,t){return t? pf.format(n/t*100)+'٪' : '۰٪'}\nfunction esc(s){return String(s==null?'':s).replace(/[&<>\"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]})}\nfunction $(id){return document.getElementById(id)}\nfunction clone(x){return JSON.parse(JSON.stringify(x))}\nfunction indexOrig(){ORIG={};SERVER.rows.forEach(function(r){ORIG[r.id]=r});REMOVED={}}\nfunction live(){return RAW.filter(function(r){return !REMOVED[r.id]})}\nfunction editing(){return document.body.classList.contains('editing')}\nfunction isDirty(r){var o=ORIG[r.id]; return !o || o.cat!==r.cat || o.req!==r.req || o.status!==r.status || o.note!==r.note}\nfunction changes(){\n  var c=0; RAW.forEach(function(r){ if(REMOVED[r.id]){ if(ORIG[r.id]) c++; } else if(isDirty(r)) c++; });\n  var ids={}; RAW.forEach(function(r){ids[r.id]=1}); Object.keys(ORIG).forEach(function(id){ if(!ids[id]) c++; });\n  return c;\n}\nfunction fmtDate(iso){\n  try{var d=new Date(iso);\n    return new Intl.DateTimeFormat('fa-IR-u-ca-persian',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Asia/Tehran'}).format(d)+' ساعت '+new Intl.DateTimeFormat('fa-IR',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Tehran'}).format(d);\n  }catch(e){return ''}\n}\nfunction updLabel(){\n  if(SERVER.updatedAt) return fmtDate(SERVER.updatedAt)+(SERVER.updatedBy?' · '+SERVER.updatedBy:'');\n  return SERVER.label||'—';\n}\nvar toastT;\nfunction toast(msg,bad){var t=$('toast');t.textContent=msg;t.className='toast show'+(bad?' bad':'');clearTimeout(toastT);toastT=setTimeout(function(){t.className='toast'},4200)}\n\nfunction tally(rows,key){\n  var order=[], m={};\n  rows.forEach(function(r){var v=r[key]; if(!(v in m)){m[v]=0;order.push(v)} m[v]++});\n  return order.map(function(v){return {name:v,n:m[v]}});\n}\nfunction catOrder(){ var o=[]; live().forEach(function(r){ if(o.indexOf(r.cat)<0) o.push(r.cat) }); return o; }\n\nfunction renderSummary(){\n  var rowsAll=live(), total=rowsAll.length, cats=tally(rowsAll,'cat');\n  var sts=tally(rowsAll,'status').sort(function(a,b){return stOrder(a.name,b.name)});\n  $('tcount').textContent=N(total); $('ccount').textContent=N(cats.length); $('upd').textContent=updLabel();\n  if(!total){['tiles','insights','donut','subs','legend'].forEach(function(id){$(id).innerHTML=''});$('dn').textContent='۰';$('dt').textContent='نیازمندی';return}\n\n  /* کاشی هر وضعیت، بدون ادغام */\n  $('tiles').innerHTML=sts.map(function(s){\n    var m=meta(s.name);\n    return '<button class=\"tile\" type=\"button\" data-status=\"'+esc(s.name)+'\" aria-pressed=\"'+(state.status===s.name)+'\" style=\"--c:'+m.color+'\"><span class=\"name\">'+esc(s.name)+'</span><span class=\"pct\">'+P(s.n,total)+'</span><span class=\"cnt\">'+N(s.n)+' نیازمندی از '+N(total)+'</span><span class=\"track\"><i style=\"width:'+(s.n/total*100)+'%\"></i></span></button>';\n  }).join('');\n\n  /* نمودار حلقه‌ای */\n  var acc=0, svg='<circle r=\"15.9155\" cx=\"21\" cy=\"21\" style=\"stroke:var(--line);cursor:default;stroke-width:6.5\"></circle>';\n  sts.forEach(function(s){\n    var v=s.n/total*100, m=meta(s.name), d=Math.max(v-0.6,0.2);\n    svg+='<circle class=\"'+(state.status===s.name?'on':'')+'\" r=\"15.9155\" cx=\"21\" cy=\"21\" pathLength=\"100\" stroke-dasharray=\"'+d+' '+(100-d)+'\" stroke-dashoffset=\"'+(-acc)+'\" style=\"stroke:'+m.color+'\" data-status=\"'+esc(s.name)+'\" tabindex=\"0\" role=\"button\"><title>'+esc(s.name)+' — '+N(s.n)+' مورد ('+P(s.n,total)+')</title></circle>';\n    acc+=v;\n  });\n  $('donut').innerHTML=svg;\n  $('donut').classList.toggle('has-sel',!!state.status);\n  var sel=state.status&&sts.filter(function(s){return s.name===state.status})[0];\n  $('dn').textContent=sel?P(sel.n,total):N(total);\n  $('dt').textContent=sel?sel.name:'نیازمندی';\n\n  /* نکات کلیدی: فقط بر پایه‌ی وضعیت‌های تکی */\n  var rates=cats.map(function(c){var rows=rowsAll.filter(function(r){return r.cat===c.name});return {name:c.name,n:c.n,done:rows.filter(function(r){return isDone(r.status)}).length}});\n  var top=sts.slice().sort(function(a,b){return b.n-a.n})[0];\n  var best=rates.slice().sort(function(a,b){return b.done/b.n-a.done/a.n||b.n-a.n})[0];\n  var zero=rates.filter(function(r){return r.done===0});\n  var worst=rates.slice().sort(function(a,b){return a.done/a.n-b.done/b.n||b.n-a.n})[0];\n  var ins='';\n  ins+='<div class=\"ins\" style=\"--ic:'+meta(top.name).color+'\"><span class=\"k\">پرتکرارترین وضعیت</span>«'+esc(top.name)+'» با <b>'+N(top.n)+' مورد</b> ('+P(top.n,total)+').</div>';\n  ins+='<div class=\"ins\" style=\"--ic:var(--s-done)\"><span class=\"k\">بیشترین «انجام شده»</span>«'+esc(best.name)+'» با <b>'+P(best.done,best.n)+'</b> ('+N(best.done)+' از '+N(best.n)+').</div>';\n  ins+= zero.length\n    ? '<div class=\"ins\" style=\"--ic:var(--s-rejected)\"><span class=\"k\">بدون هیچ مورد «انجام شده»</span>'+zero.map(function(z){return '«'+esc(z.name)+'»'}).join('، ')+'.</div>'\n    : '<div class=\"ins\" style=\"--ic:var(--s-rejected)\"><span class=\"k\">کمترین «انجام شده»</span>«'+esc(worst.name)+'» با <b>'+P(worst.done,worst.n)+'</b> ('+N(worst.done)+' از '+N(worst.n)+').</div>';\n  $('insights').innerHTML=ins;\n\n  /* بخش ۲ */\n  $('subs').innerHTML=rates.map(function(c,i){\n    var rows=rowsAll.filter(function(r){return r.cat===c.name});\n    var segs=sts.map(function(s){\n      var n=rows.filter(function(r){return r.status===s.name}).length; if(!n) return '';\n      var m=meta(s.name);\n      return '<button class=\"seg\" type=\"button\" style=\"flex:'+n+';--c:'+m.color+';--on:'+m.on+'\" data-cat=\"'+esc(c.name)+'\" data-status=\"'+esc(s.name)+'\" title=\"'+esc(s.name)+' — '+N(n)+' مورد\" aria-label=\"'+esc(c.name+'، '+s.name+'، '+N(n)+' مورد')+'\">'+N(n)+'</button>';\n    }).join('');\n    return '<div class=\"sub\"><span class=\"ix\">'+NN(i+1)+'</span><button class=\"sub-name\" type=\"button\" data-cat=\"'+esc(c.name)+'\">'+esc(c.name)+'<small>'+N(c.n)+' نیازمندی</small></button><div class=\"bar\">'+segs+'</div><div class=\"sub-pct\">'+P(c.done,c.n)+'<small>انجام شده</small></div></div>';\n  }).join('');\n  $('legend').innerHTML=sts.map(function(s){return '<span><i class=\"dot\" style=\"--c:'+meta(s.name).color+'\"></i>'+esc(s.name)+'</span>'}).join('');\n}\n\nfunction statusOptions(cur){\n  var all=CANON.slice(); RAW.forEach(function(r){ if(all.indexOf(r.status)<0) all.push(r.status) });\n  if(cur && all.indexOf(cur)<0) all.push(cur);\n  return all.map(function(s){return '<option'+(s===cur?' selected':'')+'>'+esc(s)+'</option>'}).join('');\n}\nfunction rowHTML(r,no){\n  var m=meta(r.status);\n  if(!editing()){\n    return '<article class=\"req\" data-id=\"'+esc(r.id)+'\" style=\"--c:'+m.color+'\"><div class=\"no\">'+N(no)+'</div><div class=\"tx\">'+esc(r.req)+'</div><span class=\"pill\" style=\"--c:'+m.color+'\"><i class=\"dot\" style=\"--c:'+m.color+'\"></i>'+esc(r.status)+'</span>'+(r.note?'<div class=\"note\"><b>توضیحات</b>'+esc(r.note)+'</div>':'')+'</article>';\n  }\n  var cls='req ed'+(REMOVED[r.id]?' removed':'')+(!ORIG[r.id]?' new':(isDirty(r)?' dirty':''));\n  return '<article class=\"'+cls+'\" data-id=\"'+esc(r.id)+'\" style=\"--c:'+m.color+'\"><div class=\"no\">'+N(no)+'</div>'+\n    '<textarea class=\"tx-in\" data-f=\"req\" aria-label=\"شرح نیازمندی '+N(no)+'\" placeholder=\"شرح نیازمندی\">'+esc(r.req)+'</textarea>'+\n    '<div class=\"side\"><span class=\"lbl-s\">آخرین وضعیت</span><select data-f=\"status\" style=\"--c:'+m.color+'\" aria-label=\"وضعیت نیازمندی '+N(no)+'\">'+statusOptions(r.status)+'</select>'+\n    '<button class=\"rm\" type=\"button\" data-act=\"rm\">'+(REMOVED[r.id]?'بازگرداندن':'حذف')+'</button></div>'+\n    '<textarea class=\"nt\" data-f=\"note\" aria-label=\"توضیحات نیازمندی '+N(no)+'\" placeholder=\"توضیحات (اختیاری)\">'+esc(r.note)+'</textarea></article>';\n}\nfunction filtersOn(){return !!(state.status||state.cat||state.q.trim())}\nfunction renderList(){\n  var q=state.q.trim();\n  var nums={}; RAW.forEach(function(r,i){nums[r.id]=i+1});\n  var rows=RAW.filter(function(r){\n    if(REMOVED[r.id]&&!editing()) return false;\n    if(state.status&&r.status!==state.status) return false;\n    if(state.cat&&r.cat!==state.cat) return false;\n    if(q&&(r.req+' '+r.note+' '+r.status+' '+r.cat).indexOf(q)<0) return false;\n    return true;\n  });\n  var chips='';\n  if(state.status) chips+='<button class=\"chip\" type=\"button\" data-clear=\"status\"><i class=\"dot\" style=\"--c:'+meta(state.status).color+'\"></i>وضعیت: '+esc(state.status)+' ✕</button>';\n  if(state.cat) chips+='<button class=\"chip\" type=\"button\" data-clear=\"cat\">زیرسیستم: '+esc(state.cat)+' ✕</button>';\n  $('chips').innerHTML=chips;\n  var L=live().length, shown=rows.filter(function(r){return !REMOVED[r.id]}).length;\n  $('count').textContent=filtersOn()? N(shown)+' نیازمندی از '+N(L)+' با فیلتر فعلی' : N(L)+' نیازمندی در '+N(catOrder().length)+' زیرسیستم';\n  if(!rows.length){$('list').innerHTML='<div class=\"empty\">با این فیلترها موردی پیدا نشد. «حذف فیلترها» را بزنید.</div>';return}\n\n  var order=catOrder(); RAW.forEach(function(r){ if(order.indexOf(r.cat)<0) order.push(r.cat) });\n  var groups=order.map(function(c){return {cat:c,items:rows.filter(function(r){return r.cat===c})}}).filter(function(g){return g.items.length});\n  var allOpen=true;\n  $('list').innerHTML=groups.map(function(g){\n    var ix=order.indexOf(g.cat)+1, act=g.items.filter(function(r){return !REMOVED[r.id]});\n    var open=filtersOn()||editing()||!!OPEN[g.cat]; if(!open) allOpen=false;\n    var full=live().filter(function(r){return r.cat===g.cat}), done=full.filter(function(r){return isDone(r.status)}).length;\n    var bar=tally(full,'status').sort(function(a,b){return stOrder(a.name,b.name)}).map(function(s){return '<i style=\"flex:'+s.n+';--c:'+meta(s.name).color+'\" title=\"'+esc(s.name)+': '+N(s.n)+'\"></i>'}).join('');\n    var sub=filtersOn()? N(act.length)+' از '+N(full.length)+' نیازمندی' : N(full.length)+' نیازمندی · '+N(done)+' انجام شده';\n    return '<section class=\"sys'+(open?' open':'')+'\" data-sys=\"'+esc(g.cat)+'\">'+\n      '<div class=\"sys-h\"><button class=\"sys-t\" type=\"button\" data-act=\"toggle\" aria-expanded=\"'+open+'\">'+\n        '<span class=\"sys-ix\">'+NN(ix)+'</span><span class=\"sys-name\">'+esc(g.cat)+'<small>'+sub+'</small></span><span class=\"sys-bar\" aria-hidden=\"true\">'+bar+'</span><span class=\"chev\" aria-hidden=\"true\">▾</span></button>'+\n        (editing()?'<button class=\"sys-add\" type=\"button\" data-act=\"add\" data-cat=\"'+esc(g.cat)+'\">+ نیازمندی</button>':'')+\n      '</div><div class=\"sys-body\">'+g.items.map(function(r){return rowHTML(r,nums[r.id])}).join('')+'</div></section>';\n  }).join('');\n  $('toggleall').textContent=allOpen?'بستن همه':'باز کردن همه';\n  $('toggleall').disabled=filtersOn()||editing();\n}\nfunction renderState(){\n  var c=changes();\n  $('estate').innerHTML='حالت ویرایش · '+esc(AUTH?AUTH.name:'')+' · '+(c?'<b>'+N(c)+' تغییر ذخیره‌نشده</b>':'بدون تغییر');\n  $('save').disabled=!c; $('discard').disabled=!c;\n}\nfunction render(scroll){\n  renderSummary(); renderList(); if(editing()) renderState();\n  if(scroll) $('details').scrollIntoView({behavior:'smooth',block:'start'});\n}\nfunction openSys(cat){\n  OPEN[cat]=1; render(false);\n  var el=document.querySelector('.sys[data-sys=\"'+(window.CSS&&CSS.escape?CSS.escape(cat):cat)+'\"]');\n  if(el) el.scrollIntoView({behavior:'smooth',block:'start'});\n}\n\n/* کلیک‌ها: فیلتر وضعیت، رفتن به زیرسیستم، باز و بسته کردن */\ndocument.addEventListener('click',function(e){\n  var a=e.target.closest('[data-act]');\n  if(a){ onAct(a); return; }\n  var t=e.target.closest('[data-status],[data-cat],[data-clear]'); if(!t||t.tagName==='SELECT') return;\n  if(t.dataset.clear){state[t.dataset.clear]=null;render(false);return}\n  var s=t.dataset.status, c=t.dataset.cat;\n  if(s&&c){state.status=s;state.cat=c;render(true);return}\n  if(s){state.status=(state.status===s?null:s);state.cat=null;render(true);return}\n  if(c){state.status=null;state.cat=null;state.q='';$('q').value='';openSys(c);return}\n});\ndocument.addEventListener('keydown',function(e){\n  if((e.key==='Enter'||e.key===' ')&&e.target.matches('.donut circle[data-status]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}\n  if(e.key==='Escape'){document.querySelectorAll('.modal.open').forEach(function(m){m.classList.remove('open')})}\n});\n$('q').addEventListener('input',function(e){state.q=e.target.value;renderList()});\n$('clear').addEventListener('click',function(){state={status:null,cat:null,q:''};$('q').value='';render(false)});\n$('toggleall').addEventListener('click',function(){\n  var cats=catOrder(), all=cats.every(function(c){return OPEN[c]});\n  OPEN={}; if(!all) cats.forEach(function(c){OPEN[c]=1}); renderList();\n});\n\n/* ویرایش ردیف‌ها */\nfunction rowById(id){for(var i=0;i<RAW.length;i++) if(RAW[i].id===id) return RAW[i]}\nfunction markRow(el,r){ el.classList.toggle('dirty',!!ORIG[r.id]&&isDirty(r)&&!REMOVED[r.id]); }\n$('list').addEventListener('input',function(e){\n  var f=e.target.dataset.f; if(!f||f==='status') return;\n  var el=e.target.closest('.req'), r=rowById(el.dataset.id); if(!r) return;\n  r[f]=e.target.value; markRow(el,r); renderState();\n});\n$('list').addEventListener('change',function(e){\n  if(e.target.dataset.f!=='status') return;\n  var el=e.target.closest('.req'), r=rowById(el.dataset.id); if(!r) return;\n  r.status=e.target.value; var c=meta(r.status).color;\n  e.target.style.setProperty('--c',c); el.style.setProperty('--c',c);\n  markRow(el,r); renderSummary(); renderState();\n});\nfunction onAct(a){\n  var act=a.dataset.act;\n  if(act==='toggle'){\n    var sys=a.closest('.sys'), cat=sys.dataset.sys;\n    if(filtersOn()||editing()){ sys.classList.toggle('open'); a.setAttribute('aria-expanded',sys.classList.contains('open')); return; }\n    if(OPEN[cat]) delete OPEN[cat]; else OPEN[cat]=1; renderList(); return;\n  }\n  if(act==='rm'){\n    var el=a.closest('.req'), id=el.dataset.id;\n    if(!ORIG[id]){ RAW=RAW.filter(function(x){return x.id!==id}); }\n    else { if(REMOVED[id]) delete REMOVED[id]; else REMOVED[id]=1; }\n    render(false); return;\n  }\n  if(act==='add'){ addRow(a.dataset.cat); return; }\n  if(act==='restore'){ restore(+a.dataset.v,a); return; }\n}\nfunction newId(){return 'n'+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}\nfunction addRow(cat){\n  var last=-1; RAW.forEach(function(r,i){if(r.cat===cat) last=i});\n  var r={id:newId(),cat:cat,req:'',status:'در حال انجام',note:''};\n  if(last<0) RAW.push(r); else RAW.splice(last+1,0,r);\n  state={status:null,cat:cat,q:''}; $('q').value=''; OPEN[cat]=1;\n  render(false);\n  var ta=document.querySelector('.req[data-id=\"'+r.id+'\"] textarea'); if(ta){ta.focus();ta.scrollIntoView({block:'center'})}\n}\n\n/* ورود */\nfunction openM(id){$(id).classList.add('open');var f=$(id).querySelector('input');if(f)setTimeout(function(){f.focus()},30)}\nfunction closeM(id){$(id).classList.remove('open')}\ndocument.querySelectorAll('[data-close]').forEach(function(b){b.addEventListener('click',function(){b.closest('.modal').classList.remove('open')})});\ndocument.querySelectorAll('.modal').forEach(function(m){m.addEventListener('click',function(e){if(e.target===m) m.classList.remove('open')})});\n\n$('editbtn').addEventListener('click',function(){\n  if(SERVER.readonly){toast('ذخیره‌سازی آنلاین فعال نیست. این نسخه فقط برای مشاهده است.',true);return}\n  if(editing()){return}\n  $('lg-err').textContent=''; try{$('lg-name').value=localStorage.getItem('vg-name')||''}catch(e){}\n  openM('m-login');\n});\n$('lg-form').addEventListener('submit',function(e){\n  e.preventDefault();\n  var name=$('lg-name').value.trim(), pw=$('lg-pw').value;\n  if(!name||!pw) return;\n  $('lg-go').disabled=true; $('lg-err').textContent='';\n  api('POST','/api/login',null,pw).then(function(){\n    AUTH={pw:pw,name:name}; try{localStorage.setItem('vg-name',name)}catch(e){}\n    $('lg-pw').value=''; closeM('m-login');\n    document.body.classList.add('editing'); $('editbtn').hidden=true;\n    return refresh(true);\n  }).catch(function(err){ $('lg-err').textContent=err.message; }).then(function(){$('lg-go').disabled=false});\n});\n$('exit').addEventListener('click',function(){\n  if(changes()&&!confirmInline('تغییرات ذخیره‌نشده از بین می‌رود. دوباره «خروج از ویرایش» را بزنید.')) return;\n  AUTH=null; document.body.classList.remove('editing'); $('editbtn').hidden=false;\n  RAW=clone(SERVER.rows); indexOrig(); render(false);\n});\nvar armed=null;\nfunction confirmInline(msg){ if(armed&&Date.now()-armed<6000){armed=null;return true} armed=Date.now(); toast(msg,true); return false }\n$('discard').addEventListener('click',function(){\n  if(!confirmInline('برای لغو همه‌ی تغییرات، دوباره «لغو تغییرات» را بزنید.')) return;\n  RAW=clone(SERVER.rows); indexOrig(); render(false); toast('تغییرات لغو شد.');\n});\n$('addcat').addEventListener('click',function(){ $('ct-name').value=''; openM('m-cat'); });\n$('ct-form').addEventListener('submit',function(e){\n  e.preventDefault(); var n=$('ct-name').value.trim(); if(!n) return;\n  closeM('m-cat'); addRow(n);\n});\n\n/* ارتباط با سرور */\nfunction api(method,path,body,pw){\n  var h={'Content-Type':'application/json'}; if(pw) h['Authorization']='Bearer '+pw;\n  return fetch(path,{method:method,headers:h,body:body?JSON.stringify(body):undefined,cache:'no-store'}).then(function(res){\n    return res.json().catch(function(){return {}}).then(function(j){\n      if(!res.ok){var e=new Error(j.error||('خطای سرور ('+res.status+')'));e.status=res.status;e.data=j;throw e}\n      return j;\n    });\n  }, function(){ throw new Error('ارتباط با سرور برقرار نشد. اینترنت را بررسی کنید.') });\n}\nfunction adopt(d){ SERVER=d; RAW=clone(d.rows); indexOrig(); render(false); }\nfunction refresh(quiet){ return api('GET','/api/data').then(function(d){ adopt(d); if(!quiet) toast('آخرین نسخه بارگذاری شد.'); }) }\n\n$('save').addEventListener('click',function(){\n  if(!AUTH) return;\n  var rows=live().map(function(r){return {id:r.id,cat:r.cat.trim(),req:r.req.trim(),status:r.status,note:(r.note||'').trim()}});\n  var bad=rows.filter(function(r){return !r.req});\n  if(bad.length){toast(N(bad.length)+' نیازمندی متن ندارد. متن را بنویسید یا آن ردیف را حذف کنید.',true);return}\n  $('save').disabled=true; $('save').textContent='در حال ذخیره…';\n  api('PUT','/api/data',{baseVersion:SERVER.version,updatedBy:AUTH.name,rows:rows},AUTH.pw).then(function(d){\n    adopt(d); toast('ذخیره شد. نسخه '+N(d.version)+' منتشر شد.');\n  }).catch(function(err){\n    if(err.status===409 && err.data && err.data.current){\n      rebase(err.data.current);\n      toast('همکار دیگری در این فاصله نسخه '+N(err.data.current.version)+' را ذخیره کرده بود. تغییرات شما روی نسخه‌ی جدید اعمال شد؛ بررسی کنید و دوباره ذخیره کنید.',true);\n    }\n    else if(err.status===401){toast('رمز معتبر نیست. دوباره وارد شوید.',true);}\n    else toast(err.message,true);\n  }).then(function(){ $('save').textContent='ذخیره و انتشار'; renderState(); });\n});\n/* تغییرات کاربر (بر اساس شناسه‌ی هر بند) روی نسخه‌ی جدیدتر سرور دوباره اعمال می‌شود */\nfunction rebase(d){\n  var edits=[], adds=[], rem=Object.keys(REMOVED);\n  RAW.forEach(function(r){ if(!ORIG[r.id]) adds.push(clone(r)); else if(isDirty(r)) edits.push(clone(r)); });\n  SERVER=d; RAW=clone(d.rows); indexOrig();\n  edits.forEach(function(e){ var r=rowById(e.id); if(r){r.cat=e.cat;r.req=e.req;r.status=e.status;r.note=e.note} });\n  rem.forEach(function(id){ if(ORIG[id]) REMOVED[id]=1 });\n  adds.forEach(function(a){ RAW.push(a) });\n  render(false);\n}\n\n$('histbtn').addEventListener('click',function(){\n  $('hs-err').textContent=''; $('hs-list').innerHTML='<div>در حال بارگذاری…</div>'; openM('m-hist');\n  api('GET','/api/history',null,AUTH.pw).then(function(h){\n    $('hs-list').innerHTML = h.items.length ? h.items.map(function(it){\n      return '<div><span>نسخه '+N(it.version)+' · '+esc(fmtDate(it.updatedAt))+(it.updatedBy?' · '+esc(it.updatedBy):'')+' · '+N(it.count)+' بند</span>'+\n        (it.version===SERVER.version?'<b>فعلی</b>':'<button class=\"btn ghost\" type=\"button\" data-act=\"restore\" data-v=\"'+it.version+'\">بازگردانی</button>')+'</div>';\n    }).join('') : '<div>هنوز نسخه‌ای ذخیره نشده است.</div>';\n  }).catch(function(err){$('hs-err').textContent=err.message});\n});\nfunction restore(v,btn){\n  if(changes()){ $('hs-err').textContent='اول تغییرات ذخیره‌نشده را ذخیره یا لغو کنید.'; return; }\n  btn.disabled=true;\n  api('POST','/api/restore',{version:v,baseVersion:SERVER.version,updatedBy:AUTH.name},AUTH.pw).then(function(d){\n    adopt(d); closeM('m-hist'); toast('نسخه '+N(v)+' بازگردانی و به‌عنوان نسخه '+N(d.version)+' منتشر شد.');\n  }).catch(function(err){ $('hs-err').textContent=err.message; btn.disabled=false; });\n}\n\nwindow.addEventListener('beforeunload',function(e){ if(editing()&&changes()){e.preventDefault();e.returnValue='';} });\n\n/* جایگزینی کامل با اکسل جدید (در حالت ویرایش؛ بعد باید ذخیره شود) */\n$('upbtn').addEventListener('click',function(){$('file').click()});\n$('file').addEventListener('change',function(e){\n  var f=e.target.files[0]; if(!f) return; e.target.value='';\n  toast('در حال خواندن فایل…');\n  function parse(){\n    f.arrayBuffer().then(function(buf){\n      var wb=XLSX.read(buf,{type:'array'}), ws=wb.Sheets[wb.SheetNames[0]];\n      var a=XLSX.utils.sheet_to_json(ws,{header:1,defval:''}), out=[], cat='';\n      for(var i=1;i<a.length;i++){\n        var r=a[i], c0=String(r[0]||'').trim(), req=String(r[1]||'').replace(/\\s+/g,' ').trim();\n        if(c0) cat=c0; if(!req) continue;\n        out.push({id:newId(),cat:cat||'بدون زیرسیستم',req:req,status:String(r[2]||'').trim()||'در حال انجام',note:String(r[3]||'').trim()});\n      }\n      if(!out.length) throw new Error('empty');\n      RAW.forEach(function(r){ if(ORIG[r.id]) REMOVED[r.id]=1; });\n      RAW=RAW.filter(function(r){return ORIG[r.id]}).concat(out);\n      state={status:null,cat:null,q:''}; $('q').value='';\n      render(false);\n      toast(N(out.length)+' نیازمندی از «'+f.name+'» خوانده شد. برای انتشار «ذخیره و انتشار» را بزنید.');\n    }).catch(function(){toast('فایل خوانده نشد. برگه‌ی اول باید چهار ستون «زیرسیستم، نیازمندی، آخرین وضعیت، توضیحات» را داشته باشد.',true)});\n  }\n  if(window.XLSX) return parse();\n  var s=document.createElement('script');\n  s.src='https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';\n  s.onload=parse; s.onerror=function(){toast('کتابخانه‌ی خواندن اکسل بارگذاری نشد.',true)};\n  document.head.appendChild(s);\n});\n\nrender(false);\n</script>\n</body>\n</html>\n";
