const KEY_DATA = "data";
const KEY_HIST = "history";
const HISTORY_MAX = 20;
const MAX_ROWS = 1000;
const MAX_BODY = 512 * 1024;

const CSP = [
  "default-src 'self'",
  "script-src 'self' 'unsafe-inline' https://cdnjs.cloudflare.com",
  "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
  "font-src https://fonts.gstatic.com",
  "img-src 'self' data:",
  "connect-src 'self'",
  "frame-ancestors 'none'",
  "base-uri 'none'",
  "form-action 'none'",
].join("; ");

const BASE_HEADERS = {
  "X-Robots-Tag": "noindex, nofollow",
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "DENY",
  "Referrer-Policy": "no-referrer",
  "Strict-Transport-Security": "max-age=31536000",
};

function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), {
    status,
    headers: { ...BASE_HEADERS, "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" },
  });
}
const fail = (status, error, extra = {}) => json({ error, ...extra }, status);

async function readData(env) {
  if (!env.DATA) return { ...SEED, readonly: true };
  const d = await env.DATA.get(KEY_DATA, { type: "json" });
  return d || SEED;
}

async function sha256(s) {
  return new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s)));
}
/* مقایسه با زمان ثابت روی هش‌ها تا طول و محتوای رمز از زمان پاسخ لو نرود */
async function checkAuth(request, env) {
  if (!env.ADMIN_PASSWORD) return "رمز ویرایش (ADMIN_PASSWORD) در تنظیمات Worker تعریف نشده است.";
  const h = request.headers.get("Authorization") || "";
  const given = h.startsWith("Bearer ") ? h.slice(7) : "";
  const [a, b] = await Promise.all([sha256(given), sha256(env.ADMIN_PASSWORD)]);
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];
  if (diff !== 0 || !given) {
    await new Promise((r) => setTimeout(r, 900)); /* کند کردن حدس زدن رمز */
    return "رمز ویرایش اشتباه است.";
  }
  return null;
}

function str(v, max, name, required) {
  if (v == null) v = "";
  if (typeof v !== "string") throw new Error(`فیلد ${name} باید متن باشد.`);
  v = v.trim();
  if (required && !v) throw new Error(`فیلد ${name} خالی است.`);
  if (v.length > max) throw new Error(`فیلد ${name} بیش از ${max} نویسه است.`);
  return v;
}
function cleanRows(rows) {
  if (!Array.isArray(rows) || rows.length === 0) throw new Error("فهرست نیازمندی‌ها خالی است.");
  if (rows.length > MAX_ROWS) throw new Error(`حداکثر ${MAX_ROWS} نیازمندی مجاز است.`);
  const seen = new Set();
  return rows.map((r, i) => {
    if (!r || typeof r !== "object") throw new Error(`ردیف ${i + 1} نامعتبر است.`);
    const id = str(r.id, 40, "شناسه", true);
    if (seen.has(id)) throw new Error(`شناسه‌ی تکراری در ردیف ${i + 1}.`);
    seen.add(id);
    return {
      id,
      cat: str(r.cat, 200, "زیرسیستم", true),
      req: str(r.req, 4000, "نیازمندی", true),
      status: str(r.status, 150, "وضعیت", true),
      note: str(r.note, 4000, "توضیحات", false),
    };
  });
}

async function writeVersion(env, current, rows, updatedBy) {
  const next = {
    version: (current.version || 0) + 1,
    updatedAt: new Date().toISOString(),
    updatedBy,
    label: current.label || "",
    rows,
  };
  const hist = (await env.DATA.get(KEY_HIST, { type: "json" })) || [];
  hist.unshift({ version: next.version, updatedAt: next.updatedAt, updatedBy, rows });
  await env.DATA.put(KEY_DATA, JSON.stringify(next));
  await env.DATA.put(KEY_HIST, JSON.stringify(hist.slice(0, HISTORY_MAX)));
  return next;
}

async function readBody(request) {
  const len = +(request.headers.get("Content-Length") || 0);
  if (len > MAX_BODY) throw new Error("حجم داده بیش از حد مجاز است.");
  const text = await request.text();
  if (text.length > MAX_BODY) throw new Error("حجم داده بیش از حد مجاز است.");
  try { return JSON.parse(text); } catch { throw new Error("داده‌ی ارسالی JSON معتبر نیست."); }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const p = url.pathname;
    const m = request.method;

    try {
      if (p === "/" && (m === "GET" || m === "HEAD")) {
        const data = await readData(env);
        const boot = JSON.stringify(data).replace(/</g, "\\u003c").replace(/[\u2028\u2029]/g, (c) => "\\u" + c.charCodeAt(0).toString(16));
        return new Response(HTML.replace("/*__BOOT__*/null", () => boot), {
          headers: { ...BASE_HEADERS, "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store", "Content-Security-Policy": CSP },
        });
      }

      if (p === "/api/data" && m === "GET") return json(await readData(env));

      if (!p.startsWith("/api/")) return new Response("Not found", { status: 404, headers: BASE_HEADERS });

      /* همه‌ی مسیرهای زیر رمز لازم دارند */
      if (!env.DATA) return fail(503, "فضای ذخیره‌سازی (KV با نام DATA) به Worker متصل نشده است.");
      const authErr = await checkAuth(request, env);
      if (authErr) return fail(authErr.includes("تعریف نشده") ? 503 : 401, authErr);

      if (p === "/api/login" && m === "POST") return json({ ok: true });

      if (p === "/api/history" && m === "GET") {
        const hist = (await env.DATA.get(KEY_HIST, { type: "json" })) || [];
        return json({ items: hist.map((h) => ({ version: h.version, updatedAt: h.updatedAt, updatedBy: h.updatedBy, count: h.rows.length })) });
      }

      if (p === "/api/data" && m === "PUT") {
        const body = await readBody(request);
        const current = await readData(env);
        if (body.baseVersion !== current.version) return fail(409, "نسخه‌ی جدیدتری ذخیره شده است.", { current });
        const rows = cleanRows(body.rows);
        const by = str(body.updatedBy, 60, "نام ویرایشگر", true);
        return json(await writeVersion(env, current, rows, by));
      }

      if (p === "/api/restore" && m === "POST") {
        const body = await readBody(request);
        const current = await readData(env);
        if (body.baseVersion !== current.version) return fail(409, "نسخه‌ی جدیدتری ذخیره شده است. صفحه را تازه کنید.", { current });
        const hist = (await env.DATA.get(KEY_HIST, { type: "json" })) || [];
        const h = hist.find((x) => x.version === body.version);
        if (!h) return fail(404, "این نسخه در تاریخچه پیدا نشد.");
        const by = str(body.updatedBy, 60, "نام ویرایشگر", true) + ` (بازگردانی نسخه ${body.version})`;
        return json(await writeVersion(env, current, h.rows, by.slice(0, 80)));
      }

      return fail(405, "این عملیات پشتیبانی نمی‌شود.");
    } catch (e) {
      return fail(400, e && e.message ? e.message : "درخواست نامعتبر است.");
    }
  },
};
